examples.source:
graph transformExample {
  transform result {
    value = ctx.value
  }
}

graph resourceExample {
  node lookup : httpResource {
    input {
      resourceId = ctx.resourceId
      params = {}
    }
  }
  transform result {
    payload = lookup.output.payload
  }
}

graph decisionExample {
  decision_table policy(score = ctx.score) hit=unique -> { decision: String } {
    rule (score: score >= 120) -> { decision: "accept" }
    otherwise -> { decision: "review" }
  }
}
